mapper.sql:
SELECT m.* FROM sys_trade_agent_message m
JOIN sys_trade_agent_session s ON s.session_id = m.session_id
WHERE s.user_id = #{userId} AND s.session_id = #{sessionId}

mapper.update:
UPDATE sys_trade_agent_session
SET total_tokens = total_tokens + #{tokens}, updated_at = CURRENT_TIMESTAMP
, brief_json = #{briefJson}
WHERE session_id = #{sessionId} AND user_id = #{userId}

UPDATE sys_trade_agent_session
SET title = #{title}
WHERE session_id = #{sessionId} AND user_id = #{userId} AND title = #{defaultTitle}

mapper.delete:
DELETE m FROM sys_trade_agent_message m
JOIN sys_trade_agent_session s ON s.session_id = m.session_id
WHERE s.user_id = #{userId} AND s.session_id = #{sessionId}
